import java.io.*;import java.awt.*;import java.awt.image.*;import javax.imageio.ImageIO;import com.koios.client.arpg.*;import com.koios.client.graphic.*;import com.koios.client.cache.Decompressor;import com.koios.client.stream.StreamLoader;import com.koios.game.arpg.SkillState;
public class LoadoutLayoutPreview {public static void main(String[] args)throws Exception{try(RandomAccessFile data=new RandomAccessFile("../koios-cache/main_file_cache.dat","r");RandomAccessFile index=new RandomAccessFile("../koios-cache/main_file_cache.idx0","r")){TextDrawingArea font=new TextDrawingArea(false,"p12_full",new StreamLoader(new Decompressor(data,index,1).decompress(1)));BufferedImage sheet=new BufferedImage(1032,350,BufferedImage.TYPE_INT_RGB);Graphics2D graphics=sheet.createGraphics();SkillState state=new SkillState();state.learnSupport(0,1,1);state.learnSupport(1,1,1);state.learnSupport(2,1,1);state.attach(0,0,true);state.assign(1,3);state.clear(2);String[] payload=state.update(50).split("\\|");for(int page=0;page<2;page++){BufferedImage image=new BufferedImage(512,334,BufferedImage.TYPE_INT_RGB);java.util.Arrays.fill(((DataBufferInt)image.getRaster().getDataBuffer()).getData(),0x141B22);DrawingArea.initDrawingArea(334,512,((DataBufferInt)image.getRaster().getDataBuffer()).getData());SkillDragState drag=new SkillDragState();drag.page=page;SkillPanel.draw(font,drag,payload,-1,-1);graphics.drawImage(image,page*516,0,null);}graphics.dispose();ImageIO.write(sheet,"png",new File("build/loadout-layout.png"));}}}
